function _picdicStripQueryHash(url) {
    return String(url || '').split('#')[0].split('?')[0];
}

function _picdicEnsureTrailingSlash(url) {
    url = String(url || '');
    return url && url.charAt(url.length - 1) !== '/' ? url + '/' : url;
}

function _picdicResolveFSungBaseUrl() {
    if (global._picdic_fsung_base_path) {
        return _picdicEnsureTrailingSlash(global._picdic_fsung_base_path);
    }
    var src = _picdicStripQueryHash(_picdicComponentScriptUrl || global._picdic_component_loaded_from || '');
    if (src) {
        var slash = src.lastIndexOf('/');
        if (slash >= 0) return src.slice(0, slash + 1) + 'fonts/';
    }
    return 'fonts/';
}

function _picdicCssUrl(url) {
    return String(url || '').replace(/\\/g, '\\\\').replace(/"/g, '\\"');
}

function _picdicBuildFSungFaceCss() {
    var base = _picdicResolveFSungBaseUrl();
    var css = [];
    for (var i = 0; i < _picdicFSungFiles.length; i++) {
        var item = _picdicFSungFiles[i];
        css.push('@font-face{font-family:"' + item[0] + '";src:local("' + item[2] + '"),url("' + _picdicCssUrl(base + item[1]) + '") format("truetype");font-style:normal;font-weight:normal;font-display:swap;}');
    }
    return css.join('');
}

function _picdicWarmFSung(text) {
    // 仅预热当前可见字符；CSS fallback 会继续按缺字自动选择其余分片。
    // 不阻塞界面，也不会在 PicDic 启动时强制下载六个大字体。
    try {
        if (!document.fonts || typeof document.fonts.load !== 'function') return;
        text = String(text || '');
        if (!text) return;
        var sample = Array.from(text).slice(0, 128).join('');
        _picdicFSungFiles.forEach(function(item) {
            try { document.fonts.load('28px "' + item[0] + '"', sample).catch(function(){}); } catch (e) {}
        });
    } catch (e) {}
}
// ---- 全宋體加载结束 ----

