function codePoints(text) {
    return Array.from(String(text || ''));
}

function unique(list) {
    var seen = Object.create(null);
    var out = [];
    for (var i = 0; i < list.length; i++) {
        var value = String(list[i] || '').replace(/^<br>/, '');
        if (!value || seen[value]) continue;
        seen[value] = true;
        out.push(value);
    }
    return out;
}

function searchEngine(query, options) {
    options = options || {};
    query = String(query || '').trim();
    if (!query) return [];

    _candidateAccept = function(ch) {
        try {
            return !bridge || typeof bridge.hasCandidate !== 'function' || bridge.hasCandidate(ch);
        } catch (e) {
            return false;
        }
    };

    var result;
    try {
        result = GetMatch(
            query,
            !!options.variant,
            !!options.subdivide,
            !!options.unicodeOnly,
            999999,
            ''
        );
    } finally {
        _candidateAccept = null;
    }
    return unique(result || []);
}

function getVariantCharacters(query) {
    var chars = codePoints(String(query || '').trim());
    if (chars.length !== 1) return [];
    try {
        // GetVariant() 来自 0.9.8.5 核心：这里故意不按当前词典索引过滤，
        // “查異體”先完整展示构形库中的异体关系；真正查词时再由 PicDic 索引筛选。
        return unique(GetVariant(chars[0], '') || []);
    } catch (e) {
        return [];
    }
}

